#!/usr/bin/env python3
import sys, zlib

MAGIC = b'CP1'
ALPH = b'0123456789abcdefghijklmnopqrstuvwxyz'
VAL = {c:i for i,c in enumerate(ALPH)}

def enc(data):
    out = bytearray(MAGIC)
    lines = data.splitlines(keepends=True)
    out += len(lines).to_bytes(2, 'big')
    for line in lines:
        end = line.endswith(b'\n')
        s = line[:-1] if end else line
        if s and len(s) % 2 == 0 and all(c in b'0123456789abcdef' for c in s):
            out.append(0); out.append(len(s)//2); out += bytes.fromhex(s.decode('ascii'))
        elif s and all(c in VAL for c in s):
            out.append(1); out.append(len(s)); acc=bits=0
            for c in s:
                acc=(acc<<6)|VAL[c]; bits+=6
                if bits>=8:
                    bits-=8; out.append((acc>>bits)&255)
            if bits: out.append((acc<<(8-bits))&255)
        else:
            out.append(2); out.append(len(s)); out += s
        out.append(1 if end else 0)
    return zlib.compress(bytes(out), 9)

def dec(blob):
    d=zlib.decompress(blob)
    if d[:3] != MAGIC: raise ValueError('bad file')
    n=int.from_bytes(d[3:5], 'big'); i=5; out=bytearray()
    for _ in range(n):
        typ=d[i]; i+=1; length=d[i]; i+=1
        if typ==0:
            s=d[i:i+length].hex().encode('ascii'); i+=length
        elif typ==1:
            count=length; nb=(count*6+7)//8; raw=d[i:i+nb]; i+=nb
            vals=[]; acc=bits=0
            for b in raw:
                acc=(acc<<8)|b; bits+=8
                while bits>=6 and len(vals)<count:
                    bits-=6; vals.append((acc>>bits)&63)
            s=bytes(ALPH[v] for v in vals)
        elif typ==2:
            s=d[i:i+length]; i+=length
        else: raise ValueError('bad record')
        nl=d[i]; i+=1; out += s
        if nl: out += b'\n'
    if i != len(d): raise ValueError('trailing data')
    return bytes(out)

def main():
    if len(sys.argv)==4 and sys.argv[1]=='--decompress':
        open(sys.argv[3],'wb').write(dec(open(sys.argv[2],'rb').read()))
    elif len(sys.argv)==3:
        open(sys.argv[2],'wb').write(enc(open(sys.argv[1],'rb').read()))
    else: raise SystemExit('usage: compress.py [--decompress] input output')
if __name__=='__main__': main()

